/**
 * Regenerate `supabase/schema.sql` from the numbered migration files.
 *
 * The numbered migrations in `supabase/migrations/` are the source of truth;
 * the bundle is a convenience file for reviewers who want to create the schema
 * by pasting a single SQL file into the Supabase SQL Editor (or running it with
 * psql). Run `npm run db:bundle` after adding or changing a migration.
 */
import { readdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const migrationsDir = path.join(root, "supabase", "migrations");
const outputPath = path.join(root, "supabase", "schema.sql");

const files = (await readdir(migrationsDir))
  .filter((file) => file.endsWith(".sql"))
  .sort((a, b) => a.localeCompare(b, "en"));

if (files.length === 0) {
  throw new Error(`No migrations found in ${migrationsDir}`);
}

const parts = await Promise.all(
  files.map(async (file) => {
    const sql = await readFile(path.join(migrationsDir, file), "utf8");
    return `-- ===========================================================================\n-- Source: supabase/migrations/${file}\n-- ===========================================================================\n\n${sql.trim()}\n`;
  }),
);

const header = `-- ===========================================================================
-- QuickTab Payments — complete database schema
-- ---------------------------------------------------------------------------
-- GENERATED FILE. Do not edit this file by hand.
-- Source of truth: supabase/migrations/*.sql
-- Regenerate with: npm run db:bundle
--
-- Run this once on an empty Supabase database (local Supabase CLI or a new
-- Supabase project). It creates the same schema that the numbered migrations
-- produce.
--
-- IMPORTANT: this is a Supabase database, not plain PostgreSQL. The script
-- expects the Supabase-managed \`auth\` and \`storage\` schemas, the \`anon\`,
-- \`authenticated\`, and \`service_role\` roles, and the \`supabase_realtime\`
-- publication to exist. Use \`supabase start\` or a Supabase cloud project.
--
-- This file creates schema only. It does not create the demo restaurant, the
-- demo accounts, or any menu/order data. See README.md → "Database setup" for
-- the data import steps.
--
-- Generated from ${files.length} migrations:
${files.map((file) => `--   - ${file}`).join("\n")}
-- ===========================================================================

`;

await writeFile(outputPath, header + parts.join("\n"), "utf8");
console.log(
  `Wrote supabase/schema.sql from ${files.length} migrations (${files[0]} → ${files.at(-1)}).`,
);
